schema_ddl:
CREATE TABLE categorie_prodotti (
    id SERIAL PRIMARY KEY,
    nome_categoria TEXT NOT NULL UNIQUE
);

CREATE TABLE fornitori (
    id SERIAL PRIMARY KEY,
    ragione_sociale TEXT NOT NULL UNIQUE,
    paese TEXT NOT NULL DEFAULT 'Italia'
);

CREATE TABLE prodotti (
    id SERIAL PRIMARY KEY,
    categoria_id INT NOT NULL REFERENCES categorie_prodotti(id),
    fornitore_id INT NOT NULL REFERENCES fornitori(id),
    nome_prodotto TEXT NOT NULL,
    prezzo_listino NUMERIC(10,2) NOT NULL CHECK (prezzo_listino >= 0)
);

CREATE TABLE punti_vendita (
    id SERIAL PRIMARY KEY,
    nome_negozio TEXT NOT NULL,
    citta TEXT NOT NULL
);

CREATE TABLE vendite_flat (
    id BIGINT PRIMARY KEY,
    prodotto_id INT NOT NULL REFERENCES prodotti(id),
    punto_vendita_id INT NOT NULL REFERENCES punti_vendita(id),
    data_vendita DATE NOT NULL,
    quantita INT NOT NULL CHECK (quantita > 0),
    prezzo_unitario NUMERIC(10,2) NOT NULL CHECK (prezzo_unitario >= 0),
    importo NUMERIC(12,2) NOT NULL CHECK (importo >= 0),
    nome_categoria TEXT NOT NULL,
    nome_fornitore TEXT NOT NULL
);
